import { useTranslation } from 'react-i18next';
import { CONTROL_POINT_SIDC, DRONE_SIDC, natoSymbol, targetSidc } from '../symbology/nato';

// Each entry is a NATO symbol (generated by milsymbol from a SIDC code) plus its meaning.
const ITEMS = [
  { sidc: DRONE_SIDC, key: 'drone' },
  { sidc: CONTROL_POINT_SIDC, key: 'control' },
  { sidc: targetSidc('detected'), key: 'targetDetected' },
  { sidc: targetSidc('confirmed'), key: 'targetConfirmed' },
  { sidc: targetSidc('engaged'), key: 'targetEngaged' },
  { sidc: targetSidc('neutralized'), key: 'targetNeutralized' },
] as const;

export function Legend() {
  const { t } = useTranslation();
  return (
    <main className="legend">
      <header className="legend-header">
        <a href="/">{t('legend.back')}</a>
        <h1>{t('legend.title')}</h1>
      </header>
      <ul className="legend-list">
        {ITEMS.map((item) => (
          <li key={item.key}>
            {/* milsymbol output for our own constant SIDC codes */}
            <span className="legend-symbol" dangerouslySetInnerHTML={{ __html: natoSymbol(item.sidc, 40).asSVG() }} />
            <span>{t(`legend.${item.key}`)}</span>
          </li>
        ))}
        <li>
          <span className="legend-symbol legend-text-only">↑</span>
          <span>{t('legend.wind')}</span>
        </li>
      </ul>
    </main>
  );
}
